class CsvDual:
    def __init__(self, root: Path):
        export = root / "export"
        export.mkdir(exist_ok=True)
        self._excel = open(export / "data.excel.csv", "w", newline="", encoding="utf-8")
        self._raw   = open(export / "data.raw.csv",   "w", newline="", encoding="utf-8")
        headers = ["name","value","unit","timestamp"]
        self._excel_w = DictWriter(self._excel, fieldnames=headers)
        self._raw_w   = DictWriter(self._raw,   fieldnames=headers)
        self._excel_w.writeheader(); self._raw_w.writeheader()

    def row(self, name: str, value: float, unit: str, ts: str) -> None:
        r = {"name":name,"value":value,"unit":unit,"timestamp":ts}
        self._excel_w.writerow(r); self._raw_w.writerow(r)

    def close(self) -> None:
        for f in (self._excel, self._raw):
            f.flush(); os.fsync(f.fileno()); f.close()
        flush_dir_anchor_if_windows(Path(self._excel.name).parent)

from __future__ import annotations
from pathlib import Path
import hashlib, json
from .win_durability import flush_dir_anchor_if_windows
from .durability import atomic_open

def _sha256(p: Path) -> str:
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1<<20), b""):
            h.update(chunk)
    return h.hexdigest()

def write_layout(run_dir: Path) -> None:
    files = []
    for p in sorted(run_dir.rglob("*")):
        if p.is_file():
            files.append({
                "path": str(p.relative_to(run_dir)),
                "bytes": p.stat().st_size,
                "sha256": _sha256(p)
            })
    out = run_dir / "layout.v1.json"
    with atomic_open(out, "wb") as f:
        f.write(json.dumps(files, indent=2).encode("utf-8"))
    flush_dir_anchor_if_windows(run_dir)

