class TraceWriter:
    def __init__(self, root: Path):
        raw = _env_int("PYTAF_TRACE_INLINE_MAX", 256, 0, 4 * 1024 * 1024)
        self._inline_max = max(64, raw)
        self._enc = msgspec.json.Encoder()
        self._path = root / "trace.raw.v1.jsonl"
        self._f = open(self._path, "wb", buffering=0)
        (root / "trace.version.txt").write_text("trace.raw.v1\n", encoding="utf-8")

    def _write_row(self, row: dict) -> None:
        self._f.write(self._enc.encode(row)); self._f.write(b"\n")

    def tx(self, t_ns: int, uri: str, payload: bytes) -> None:
        self._emit("tx", t_ns, uri, payload)

    def rx(self, t_ns: int, uri: str, payload: bytes) -> None:
        self._emit("rx", t_ns, uri, payload)

    def _emit(self, dir_: str, t_ns: int, uri: str, payload: bytes) -> None:
        row = {"version":"trace.raw.v1","dir":dir_, "t_ns":t_ns, "uri":uri, "len":len(payload)}
        if len(payload) <= self._inline_max:
            row["enc"] = "b64"
            row["b64"] = base64.b64encode(payload).decode("ascii")
        else:
            h, _ = put_blob(self._path.parent, payload)
            row["enc"] = "blob"
            row["blob"] = f"sha256:{h}"
        self._write_row(row)

    def close(self) -> None:
        self._f.flush(); os.fsync(self._f.fileno()); self._f.close()
        flush_dir_anchor_if_windows(self._path.parent)

from __future__ import annotations
import os
from pathlib import Path

IS_WIN = (os.name == "nt")

class BrokerLock:
    """
    Single-byte advisory lock held exclusively by the broker while alive.
    Presence == broker alive for kill safety checks.
    """
    def __init__(self, path: str):
        self._path = Path(path)
        self._path.parent.mkdir(parents=True, exist_ok=True)
        if not self._path.exists():
            self._path.write_bytes(b"")
        self._fh = None

    @property
    def path(self) -> Path:
        return self._path

    def acquire_exclusive(self) -> None:
        if self._fh is not None:
            return
        self._fh = open(self._path, "a+b")
        try:
            if IS_WIN:
                import msvcrt
                try:
                    msvcrt.locking(self._fh.fileno(), msvcrt.LK_NBLCK, 1)
                except OSError:
                    msvcrt.locking(self._fh.fileno(), msvcrt.LK_LOCK, 1)
                    msvcrt.locking(self._fh.fileno(), msvcrt.LK_UNLCK, 1)
                    msvcrt.locking(self._fh.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl
                fcntl.flock(self._fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except Exception as e:
            try:
                self._fh.close()
            except Exception:
                pass
            self._fh = None
            raise e

    def release(self) -> None:
        if self._fh is None:
            return
        try:
            if IS_WIN:
                import msvcrt
                try:
                    msvcrt.locking(self._fh.fileno(), msvcrt.LK_UNLCK, 1)
                except Exception:
                    pass
            else:
                import fcntl
                try:
                    fcntl.flock(self._fh.fileno(), fcntl.LOCK_UN)
                except Exception:
                    pass
        finally:
            try:
                self._fh.close()
            except Exception:
                pass
            self._fh = None

def try_nonblocking_exclusive_lock(path: Path) -> bool:
    """
    Attempt to acquire an exclusive, non-blocking lock on `path`.
    Returns True if lock acquired (i.e., no one holds it), False if already locked.
    """
    fh = open(path, "a+b")
    try:
        if IS_WIN:
            import msvcrt
            try:
                msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
                msvcrt.locking(fh.fileno(), msvcrt.LK_UNLCK, 1)
                fh.close()
                return True
            except OSError:
                fh.close()
                return False
        else:
            import fcntl
            try:
                fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                fcntl.flock(fh.fileno(), fcntl.LOCK_UN)
                fh.close()
                return True
            except BlockingIOError:
                fh.close()
                return False
    except Exception:
        try:
            fh.close()
        except Exception:
            pass
        return False

